-- Seed: EC clients. is_active = has a non-Done campaign in Notion [Master] Energy Central Campaigns (11/11/2026).
alter table public.clients add column if not exists notion_aliases text[] not null default '{}';

on conflict (slug) do update set notion_partner_name = excluded.notion_partner_name,
  notion_aliases = excluded.notion_aliases, customer_report_sheet_url = excluded.customer_report_sheet_url,
  is_active = excluded.is_active;

select count(*) as total, count(*) filter (where is_active) as live, count(*) filter (where customer_report_sheet_url is null) as no_sheet from public.clients;
